/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import io.quarkus.arc.Arc;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.alert.IssueChange;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueChangeSet;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueKindOptions;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueLevelOptions;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueStatusOptions;
import net.civeira.phylax.feature.observe.observedissue.domain.gateway.ObservedIssueCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedissue.domain.gateway.ObservedIssueFilter;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;
import net.civeira.phylax.feature.observe.source.SourceRegistry;
import net.civeira.phylax.feature.observe.store.ObsLog;
import net.civeira.phylax.feature.observe.store.ObsSpan;

/**
 * Groups the error events of each batch of the writer in observed-issue: one upsert per fingerprint
 * and source (not per event). A new fingerprint creates the issue as UNRESOLVED; a known one adds
 * its count, its last occurrence and its last trace; a RESOLVED one is reopened (regression) only
 * when the error comes from a release later than the last one seen before it was resolved
 * ({@link Releases}): while the old release is still running it keeps counting without reopening.
 * An IGNORED one keeps counting without changing its state.
 *
 * <p>
 * It runs in the writer thread of the pipeline, never in the thread that logs: the database work
 * cannot block the application.
 */
@ApplicationScoped
@Slf4j
public class IssueAggregator {

  /** Package of the observability: its own logs never become issues (no feedback loop). */
  private static final String OWN_PACKAGE = "net.civeira.phylax.feature.observe";
  /** Attribute of the stored error logs with the fingerprint of their issue. */
  public static final String FINGERPRINT_ATTR = "issue.fingerprint";

  /** Occurrences of a fingerprint in one batch. */
  static final class Group {
    final IssueFingerprint.Result issue;
    int count;
    long first = Long.MAX_VALUE;
    ErrorEvent last;
    String firstRelease;
    long firstReleaseTs = Long.MAX_VALUE;
    final java.util.Set<String> releases = new java.util.TreeSet<>();
    boolean unversioned;
    boolean fatal;
    boolean performance;
    final HyperLogLog users = new HyperLogLog();
    final HyperLogLog tenants = new HyperLogLog();

    Group(final IssueFingerprint.Result issue) {
      this.issue = issue;
    }

    void add(final ErrorEvent event, final Pseudonym pseudonym) {
      if (null != pseudonym && null != event.context()) {
        users.add(pseudonym.of("who", event.context().who()));
        tenants.add(pseudonym.of("tenant", event.context().tenant()));
      }
      count++;
      first = Math.min(first, event.ts());
      if (null == last || event.ts() >= last.ts()) {
        last = event;
      }
      fatal |= "FATAL".equals(event.level());
      performance |= null != event.type() && PerformanceDetector.TYPES.contains(event.type());
      if (null == event.release() || event.release().isBlank()) {
        unversioned = true;
      } else {
        releases.add(event.release());
        if (event.ts() < firstReleaseTs) {
          firstReleaseTs = event.ts();
          firstRelease = event.release();
        }
      }
    }

    /** True if some event of the batch comes after {@code baseline} (or cannot be told). */
    boolean after(final String baseline) {
      return unversioned || releases.isEmpty()
          || releases.stream().anyMatch(release -> Releases.isAfter(release, baseline));
    }

    /** The release of the last event, or else the newest of the batch. */
    String lastRelease() {
      if (null != last.release() && !last.release().isBlank()) {
        return last.release();
      }
      return releases.stream().reduce((a, b) -> Releases.isAfter(b, a) ? b : a).orElse(null);
    }
  }

  private final ObservedIssueCommandRepositoryGateway issues;
  private final SourceRegistry registry;
  private final boolean enabled;
  private final List<String> inApp;
  /** Fingerprint rules and aliases of merged issues (null in the unit tests). */
  @jakarta.inject.Inject
  FingerprintRules fingerprintRules;
  @jakarta.inject.Inject
  IssueAliases aliases;

  /** Null when the users are not counted ({@code app.observe.issues.track-users=false}). */
  private final Pseudonym pseudonym;
  @ConfigProperty(name = "app.observe.performance.n-plus-one-min", defaultValue = "10")
  int nPlusOneMin = 10;
  @ConfigProperty(name = "app.observe.performance.n-plus-one-min-ms", defaultValue = "100")
  double nPlusOneMinMs = 100;
  @ConfigProperty(name = "app.observe.performance.slow-ms", defaultValue = "5000")
  long slowMs = 5000;

  /** Thresholds of the performance issues ({@code app.observe.performance.*}). */
  public void performance(final int minRepeats, final double minTotalMs, final long slow) {
    this.nPlusOneMin = Math.max(2, minRepeats);
    this.nPlusOneMinMs = Math.max(0, minTotalMs);
    this.slowMs = Math.max(0, slow);
  }

  public IssueAggregator(final ObservedIssueCommandRepositoryGateway issues,
      final SourceRegistry registry,
      final @ConfigProperty(name = "app.observe.issues.enabled",
          defaultValue = "true") boolean enabled,
      final @ConfigProperty(name = "app.observe.issues.in-app",
          defaultValue = "net.civeira.phylax.") String inApp,
      final @ConfigProperty(name = "app.observe.issues.track-users",
          defaultValue = "true") boolean trackUsers,
      final @ConfigProperty(name = "app.observe.issues.user-salt",
          defaultValue = "phylax-api") String salt) {
    this.issues = issues;
    this.registry = registry;
    this.enabled = enabled;
    this.inApp =
        Arrays.stream(inApp.split(",")).map(String::trim).filter(v -> !v.isEmpty()).toList();
    this.pseudonym = trackUsers ? new Pseudonym(salt) : null;
  }

  /**
   * Groups the error logs of a batch (called by the writer after storing it). The spans of the
   * batch complete the user and tenant of the errors of their trace (the error log of the front has
   * no user; the span of the back that served it does).
   */
  public List<IssueChange> record(final List<ObsLog> logs, final List<ObsSpan> spans) {
    if (!enabled || (logs.isEmpty() && (null == spans || spans.isEmpty()))) {
      return List.of();
    }
    Map<String, Group> groups = group(logs, contexts(spans));
    for (ErrorEvent event : PerformanceDetector.detect(spans, nPlusOneMin, nPlusOneMinMs, slowMs)) {
      fingerprint(event).ifPresent(
          done -> groups.computeIfAbsent(done.event().source() + "\n" + done.issue().fingerprint(),
              key -> new Group(done.issue())).add(done.event(), pseudonym));
    }
    if (groups.isEmpty()) {
      return List.of();
    }
    boolean activated = !Arc.container().requestContext().isActive();
    if (activated) {
      Arc.container().requestContext().activate();
    }
    try {
      return self().upsert(groups);
    } finally {
      if (activated) {
        Arc.container().requestContext().terminate();
      }
    }
  }

  /**
   * The logs of a batch with the fingerprint of their issue in {@link #FINGERPRINT_ATTR}, before
   * storing them: the detail of an issue finds its events by it.
   */
  public List<ObsLog> tag(final List<ObsLog> logs) {
    if (!enabled) {
      return logs;
    }
    List<ObsLog> result = new java.util.ArrayList<>(logs.size());
    for (ObsLog log : logs) {
      Optional<IssueFingerprint.Result> issue = ErrorEvents.from(log, OWN_PACKAGE)
          .flatMap(event -> fingerprint(event).map(Fingerprinted::issue));
      if (issue.isEmpty()) {
        result.add(log);
        continue;
      }
      Map<String, Object> attrs = new LinkedHashMap<>(null == log.attrs() ? Map.of() : log.attrs());
      attrs.put(FINGERPRINT_ATTR, issue.get().fingerprint());
      result.add(new ObsLog(log.ts(), log.src(), log.level(), log.logger(), log.msg(),
          log.traceId(), log.spanId(), log.error(), attrs, log.release(), log.env()));
    }
    return result;
  }

  /** An event after the fingerprint rules, with its fingerprint. */
  record Fingerprinted(ErrorEvent event, IssueFingerprint.Result issue) {}

  /**
   * The fingerprint rules of the origin decide: drop the event, group it as a rule, skip frames.
   */
  Optional<Fingerprinted> fingerprint(final ErrorEvent event) {
    if (null == fingerprintRules || fingerprintRules.all().isEmpty()) {
      return Optional.of(new Fingerprinted(event, IssueFingerprint.of(event, inApp)));
    }
    String originUid = null == registry ? null
        : registry.byCode(event.source()).map(SourceRegistry.Source::uid).orElse(null);
    FingerprintRules.Decision decision =
        FingerprintRules.apply(fingerprintRules.all(), originUid, event);
    if (decision.drop()) {
      return Optional.empty();
    }
    return Optional.of(new Fingerprinted(decision.event(),
        IssueFingerprint.of(decision.event(), inApp, decision.ignoreFrame())));
  }

  /** Prefixes of the own frames (for the stack of the viewer). */
  public List<String> inApp() {
    return inApp;
  }

  /** The error events of the batch, by source and fingerprint, in arrival order. */
  Map<String, Group> group(final List<ObsLog> logs) {
    return group(logs, Map.of());
  }

  Map<String, Group> group(final List<ObsLog> logs, final Map<String, EventContext> byTrace) {
    Map<String, Group> groups = new LinkedHashMap<>();
    for (ObsLog log : logs) {
      Optional<ErrorEvent> found = ErrorEvents.from(log, OWN_PACKAGE);
      if (found.isPresent()) {
        ErrorEvent event = null == log.traceId() ? found.get()
            : found.get().withContext(byTrace.get(log.traceId()));
        fingerprint(event).ifPresent(done -> groups
            .computeIfAbsent(done.event().source() + "\n" + done.issue().fingerprint(),
                key -> new Group(done.issue()))
            .add(done.event(), pseudonym));
      }
    }
    return groups;
  }

  /** User and tenant of each trace of the batch, from its spans (the first one that has them). */
  static Map<String, EventContext> contexts(final List<ObsSpan> spans) {
    Map<String, EventContext> result = new java.util.HashMap<>();
    if (null == spans) {
      return result;
    }
    for (ObsSpan span : spans) {
      if (null != span.traceId()) {
        EventContext context = EventContext.of(span.attrs());
        result.merge(span.traceId(), context, EventContext::orElse);
      }
    }
    return result;
  }

  /** One transaction for the whole batch; returns the new issues and the regressions. */
  @Transactional
  public List<IssueChange> upsert(final Map<String, Group> groups) {
    List<IssueChange> changes = new java.util.ArrayList<>();
    for (Group group : groups.values()) {
      Optional<SourceRegistry.Source> source = registry.byCode(group.last.source());
      if (source.isEmpty()) {
        continue;
      }
      ObservedSourceReference origin = ObservedSourceReference.of(source.get().uid());
      Optional<ObservedIssue> existing = null == aliases ? Optional.empty()
          : aliases.issueOf(source.get().uid(), group.issue.fingerprint())
              .flatMap(uid -> issues.find(ObservedIssueFilter.builder().uid(uid).build()));
      if (existing.isEmpty()) {
        existing = issues.find(ObservedIssueFilter.builder().origin(origin)
            .fingerprint(group.issue.fingerprint()).build());
      }
      // A merged issue without its alias yet: its events go to the issue it was merged into
      if (existing.isPresent() && ObservedIssueStatusOptions.MERGED == existing.get().getStatus()
          && existing.get().getMergedInto().isPresent()) {
        Optional<ObservedIssue> target = issues
            .find(ObservedIssueFilter.builder().uid(existing.get().getMergedInto().get()).build());
        if (target.isPresent()) {
          existing = target;
        }
      }
      ObservedIssue issue =
          existing.orElseGet(() -> issues.create(ObservedIssue.create(new ObservedIssueChangeSet()
              .newUid().origin(origin).fingerprint(group.issue.fingerprint())
              .title(group.issue.title()).culprit(group.issue.culprit())
              .kind(group.performance ? ObservedIssueKindOptions.PERFORMANCE
                  : ObservedIssueKindOptions.ERROR)
              .level(group.performance ? ObservedIssueLevelOptions.WARNING
                  : group.fatal ? ObservedIssueLevelOptions.FATAL
                      : ObservedIssueLevelOptions.ERROR))));
      int count = (null == issue.getCount() ? 0 : issue.getCount()) + group.count;
      OffsetDateTime first = issue.getFirstSeenAt().orElse(time(group.first));
      String baseline = issue.getRelease().orElse(null);
      // An issue ignored until a moment or a count reopens when it is reached
      boolean snoozeOver = ObservedIssueStatusOptions.IGNORED == issue.getStatus() && (issue
          .getIgnoreUntil().map(until -> until.isBefore(OffsetDateTime.now(ZoneOffset.UTC)))
          .orElse(false)
          || issue.getIgnoreUntilCount().map(limit -> limit > 0 && count >= limit).orElse(false));
      boolean regression = snoozeOver
          || (ObservedIssueStatusOptions.RESOLVED == issue.getStatus() && group.after(baseline));
      ObservedIssueStatusOptions status =
          regression ? ObservedIssueStatusOptions.UNRESOLVED : issue.getStatus();
      // A resolved issue keeps the release it was resolved after until it really regresses
      String release = ObservedIssueStatusOptions.RESOLVED == status ? baseline
          : java.util.Optional.ofNullable(group.lastRelease()).orElse(baseline);
      String firstRelease = issue.getFirstRelease().orElse(group.firstRelease);
      HyperLogLog users =
          HyperLogLog.fromBase64(issue.getUsersSketch().orElse(null)).merge(group.users);
      HyperLogLog tenants =
          HyperLogLog.fromBase64(issue.getTenantsSketch().orElse(null)).merge(group.tenants);
      if (existing.isEmpty() || regression) {
        changes.add(new IssueChange(issue.getUid(), source.get().uid(), source.get().code(),
            issue.getTitle(), issue.getLevel().name(), count,
            null == pseudonym ? 0 : (int) users.estimate(), release, regression));
      }
      issues.update(issue,
          issue.recordOccurrence(count, first, time(group.last.ts()), status,
              String.valueOf(group.last.ts()), group.last.traceId(), firstRelease, release,
              null == pseudonym ? 0 : (int) users.estimate(),
              null == pseudonym ? 0 : (int) tenants.estimate(),
              null == pseudonym ? null : users.toBase64(),
              null == pseudonym ? null : tenants.toBase64()));
    }
    return changes;
  }

  private IssueAggregator self() {
    // Through the container, so @Transactional applies (a call to this would skip it)
    return Arc.container().instance(IssueAggregator.class).get();
  }

  private static OffsetDateTime time(final long epochMillis) {
    return Instant.ofEpochMilli(epochMillis).atOffset(ZoneOffset.UTC);
  }
}
